CREATE TABLE local_retail_ops(id TEXT PRIMARY KEY NOT NULL,request TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE local_retail_pending(actor_id TEXT PRIMARY KEY REFERENCES local_principals(id),id TEXT NOT NULL UNIQUE,request TEXT NOT NULL);
CREATE TABLE local_retail_canceled(id TEXT PRIMARY KEY NOT NULL);
CREATE TABLE local_retail_payments(id TEXT PRIMARY KEY NOT NULL,invoice_id TEXT NOT NULL REFERENCES local_invoices(id),method TEXT NOT NULL CHECK(method IN ('cash','upi','card','credit')),amount INTEGER NOT NULL CHECK(amount BETWEEN 1 AND 9000000000000),reference TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX retail_invoice_payments ON local_retail_payments(invoice_id);
CREATE TABLE local_retail_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,operation_id TEXT NOT NULL,subject TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('matched','unmatched','refund_matched')),reference TEXT NOT NULL,reason TEXT NOT NULL,actor_id TEXT REFERENCES local_principals(id),created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX retail_subject_events ON local_retail_events(subject,sequence);
CREATE INDEX retail_reference_events ON local_retail_events(reference,kind);
CREATE TABLE local_retail_journal(sequence INTEGER PRIMARY KEY AUTOINCREMENT,operation_id TEXT NOT NULL,customer_id TEXT REFERENCES local_customers(id),account TEXT NOT NULL CHECK(account IN ('cash','receivables','upi_clearing','card_clearing','revenue','tax_payable','refund_payable')),amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount<>0 AND amount BETWEEN -9000000000000 AND 9000000000000));
CREATE INDEX retail_operation_journal ON local_retail_journal(operation_id);
CREATE TABLE local_retail_activity(sequence INTEGER PRIMARY KEY AUTOINCREMENT,operation_id TEXT NOT NULL UNIQUE,actor_id TEXT REFERENCES local_principals(id),day TEXT NOT NULL,kind TEXT NOT NULL,cash_delta INTEGER NOT NULL CHECK(typeof(cash_delta)='integer'),created_at TEXT NOT NULL);
CREATE INDEX retail_daily_activity ON local_retail_activity(day,actor_id,sequence);
CREATE TABLE local_retail_returns(id TEXT PRIMARY KEY NOT NULL,invoice_id TEXT NOT NULL REFERENCES local_invoices(id),subtotal INTEGER NOT NULL,tax INTEGER NOT NULL,total INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE local_retail_return_items(operation_id TEXT NOT NULL REFERENCES local_retail_returns(id),line_index INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(operation_id,line_index));
CREATE TABLE local_retail_return_parts(operation_id TEXT NOT NULL REFERENCES local_retail_returns(id),payment_id TEXT NOT NULL REFERENCES local_retail_payments(id),amount INTEGER NOT NULL CHECK(amount>0),debt INTEGER NOT NULL CHECK(debt>=0),cash_out INTEGER NOT NULL CHECK(cash_out>=0),PRIMARY KEY(operation_id,payment_id));
CREATE TABLE local_retail_refunds(id TEXT PRIMARY KEY NOT NULL,operation_id TEXT NOT NULL REFERENCES local_retail_returns(id),payment_id TEXT NOT NULL REFERENCES local_retail_payments(id),method TEXT NOT NULL CHECK(method IN ('upi','card')),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE local_retail_floats(id TEXT PRIMARY KEY NOT NULL,actor_id TEXT NOT NULL REFERENCES local_principals(id),day TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount BETWEEN 0 AND 9000000000000),UNIQUE(actor_id,day));
CREATE TABLE local_retail_float_corrections(id TEXT PRIMARY KEY NOT NULL,opening_id TEXT NOT NULL REFERENCES local_retail_floats(id),amount INTEGER NOT NULL CHECK(amount BETWEEN 0 AND 9000000000000),reason TEXT NOT NULL);
CREATE TABLE local_retail_closings(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,actor_id TEXT NOT NULL REFERENCES local_principals(id),day TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('closed','corrected','reopened')),payload TEXT NOT NULL);
CREATE INDEX retail_drawer_closings ON local_retail_closings(actor_id,day,sequence);
CREATE TABLE local_retail_outbox(sequence INTEGER PRIMARY KEY AUTOINCREMENT,operation_id TEXT NOT NULL UNIQUE REFERENCES local_retail_ops(id),payload TEXT NOT NULL);
PRAGMA user_version=9;
